<script setup lang="ts">
import { ref } from "vue"; import { useMutation, useQuery, useQueryClient } from "@tanstack/vue-query"; import { ExternalLink, LoaderCircle } from "lucide-vue-next"; import { appealKeys, decideAppeal, listAppeals } from "../../api/appeals"; import type { Appeal } from "../../shared/types/appeal";
const client = useQueryClient(); const reviewer = ref(""); const justification = ref(""); const overrideValue = ref("true"); const overrideNumber = ref(0); const active = ref<Appeal | null>(null);
const query = useQuery({ queryKey: appealKeys.queue, queryFn: ({ signal }) => listAppeals("", signal) });
const mutation = useMutation({ mutationFn: (status: "UNDER_REVIEW" | "CONFIRMED" | "OVERRIDDEN") => decideAppeal(active.value!.appeal_id, { status, reviewer: reviewer.value.trim(), justification: justification.value.trim(), ...(status === "OVERRIDDEN" ? { override_value: typeof active.value!.original_evaluation.raw_value === "number" ? overrideNumber.value : overrideValue.value === "na" ? null : overrideValue.value === "true" } : {}) }), onSuccess: async () => { active.value = null; justification.value = ""; await client.invalidateQueries({ queryKey: appealKeys.queue }); } });
function select(a: Appeal) { active.value = a; if (typeof a.original_evaluation.raw_value === "number") overrideNumber.value = a.original_evaluation.raw_value; }
</script>
<template><section><h1 class="text-2xl font-black">Appeal review workspace</h1><p class="mt-1 text-sm text-muted">Review the preserved original evaluation, claimant comment, and transcript evidence.</p><div v-if="query.isLoading.value" class="mt-6 rounded-2xl bg-white p-10 text-center text-muted">Loading appeals…</div><div v-else-if="query.isError.value" class="mt-6 rounded-2xl bg-white p-10 text-center text-red-700"><p>{{ query.error.value?.message }}</p><button class="button-secondary mt-4" @click="query.refetch()">Retry</button></div><div v-else class="mt-6 grid gap-6 lg:grid-cols-[minmax(0,1fr)_24rem]"><div class="space-y-3"><button v-for="appeal in query.data.value" :key="appeal.appeal_id" class="block w-full rounded-2xl border p-5 text-left" :class="active?.appeal_id === appeal.appeal_id ? 'border-primary bg-primary-soft' : 'border-line bg-white'" @click="select(appeal)"><div class="flex justify-between gap-3"><strong>{{ appeal.criterion_name }}</strong><span class="text-xs font-bold">{{ appeal.status.replace('_', ' ') }}</span></div><p class="mt-2 text-sm text-muted">{{ appeal.conversation_id }} · {{ appeal.comment }}</p></button><div v-if="!query.data.value?.length" class="rounded-2xl bg-white p-10 text-center text-muted">No appeals have been submitted.</div></div><aside v-if="active" class="rounded-2xl bg-white p-5 lg:sticky lg:top-24 lg:self-start"><h2 class="font-bold">{{ active.criterion_name }}</h2><p class="mt-2 text-sm"><strong>Original:</strong> {{ active.original_evaluation.raw_value === null ? 'N/A' : active.original_evaluation.raw_value }}</p><p class="mt-2 text-sm text-muted">{{ active.original_evaluation.explanation }}</p><RouterLink v-for="id in active.original_evaluation.evidence_message_ids" :key="id" class="mt-2 inline-flex items-center gap-1 text-xs font-bold text-primary" :to="{ name: 'conversation-detail', params: { id: active.conversation_id }, query: { message: id } }"><ExternalLink :size="12" /> Transcript evidence</RouterLink><div class="mt-4 rounded-xl bg-surface p-3 text-sm"><strong>Appeal:</strong> {{ active.comment }}</div><template v-if="!['CONFIRMED','OVERRIDDEN'].includes(active.status)"><input v-model="reviewer" class="field mt-4" placeholder="Reviewer name" /><textarea v-model="justification" class="field mt-3 min-h-24" placeholder="Required decision justification" /><select v-if="active.original_evaluation.answer_type === 'numeric'" v-model.number="overrideNumber" class="field mt-3" aria-label="Override numeric score"><option v-for="value in active.original_evaluation.allowed_values" :key="value" :value="value">{{ value }}</option><option v-if="active.original_evaluation.na_enabled" :value="NaN">N/A</option></select><select v-else v-model="overrideValue" class="field mt-3"><option value="true">Yes</option><option value="false">No</option><option v-if="active.original_evaluation.na_enabled" value="na">N/A</option></select><p v-if="mutation.error.value" class="mt-3 text-sm text-red-700">{{ mutation.error.value.message }}</p><button v-if="active.status === 'OPEN'" class="button-secondary mt-4 w-full" :disabled="!reviewer.trim() || !justification.trim() || mutation.isPending.value" @click="mutation.mutate('UNDER_REVIEW')">Begin review</button><div class="mt-2 grid grid-cols-2 gap-2"><button class="button-secondary" :disabled="!reviewer.trim() || !justification.trim() || mutation.isPending.value" @click="mutation.mutate('CONFIRMED')">Confirm original</button><button class="button-primary" :disabled="!reviewer.trim() || !justification.trim() || mutation.isPending.value" @click="mutation.mutate('OVERRIDDEN')"><LoaderCircle v-if="mutation.isPending.value" class="animate-spin" :size="15" /> Override</button></div></template><div v-else-if="active.decision" class="mt-4 rounded-xl bg-emerald-50 p-3 text-sm"><strong>{{ active.decision.reviewer }}</strong><p class="mt-1">{{ active.decision.justification }}</p></div></aside><aside v-else class="rounded-2xl bg-white p-8 text-center text-sm text-muted lg:sticky lg:top-24 lg:self-start">Select an appeal to review.</aside></div></section></template>
